package protocol

import "encoding/json"

type anthropicRequest struct{Model string `json:"model"`;MaxTokens int `json:"max_tokens"`;Stream bool `json:"stream"`;System any `json:"system,omitempty"`;Messages []struct{Role string `json:"role"`;Content any `json:"content"`} `json:"messages"`;Tools any `json:"tools,omitempty"`}
func AnthropicToOpenAI(body []byte)([]byte,error){var in anthropicRequest;if err:=json.Unmarshal(body,&in);err!=nil{return nil,err};msgs:=make([]map[string]any,0,len(in.Messages)+1);if in.System!=nil{msgs=append(msgs,map[string]any{"role":"system","content":in.System})};for _,m:=range in.Messages{msgs=append(msgs,map[string]any{"role":m.Role,"content":m.Content})};out:=map[string]any{"model":in.Model,"messages":msgs,"max_tokens":in.MaxTokens,"stream":in.Stream};if in.Tools!=nil{out["tools"]=in.Tools};return json.Marshal(out)}
func OpenAIToAnthropic(body []byte)([]byte,error){var in struct{ID string `json:"id"`;Model string `json:"model"`;Choices []struct{Message struct{Content any `json:"content"`;ToolCalls any `json:"tool_calls"`} `json:"message"`;FinishReason string `json:"finish_reason"`} `json:"choices"`;Usage struct{PromptTokens int `json:"prompt_tokens"`;CompletionTokens int `json:"completion_tokens"`} `json:"usage"`};if err:=json.Unmarshal(body,&in);err!=nil{return nil,err};content:=[]map[string]any{};if len(in.Choices)>0{if s,ok:=in.Choices[0].Message.Content.(string);ok&&s!=""{content=append(content,map[string]any{"type":"text","text":s})}};out:=map[string]any{"id":in.ID,"type":"message","role":"assistant","model":in.Model,"content":content,"stop_reason":"end_turn","usage":map[string]int{"input_tokens":in.Usage.PromptTokens,"output_tokens":in.Usage.CompletionTokens}};return json.Marshal(out)}
